-- Gerado por scripts/insert_natal_deco.mjs — "Cena de Natal com Luz" (rascunho, família Decoração)
insert into prod_designs (id, nome, descricao, familia, estado, acesso_maker, disponivel_consumidor, capa_familia, usa_modo, tags, preco_creditos, scad_template, generation_schema, parametros_default)
values ('cena_led', 'Cena de Natal com Luz', 'Moldura em círculo, estrela ou arco com uma cena de Natal em silhueta (renas, pinheiros, presépio, trenó ou casinhas), de pé numa base com uma vela LED por trás.', 'Decoração', 'rascunho', 'gratuito', false, false, false,
  array['cena', 'silhueta', 'presépio', 'renas', 'LED', 'natal', 'moldura'], 1, $tpl$// Cena de Natal com Luz — o modelo está em templates/decoracao/partes/cena_led.scad (backend)
include </app/templates/decoracao/cena_led.scad>
$tpl$, '{"engine":"openscad","version":1,"parameters":{"deco":{"order":0,"default":"cena_led","ui":{"widget":"hidden"}},"moldura":{"order":1,"default":"Círculo","ui":{"label":"Moldura","widget":"select","options":["Círculo","Estrela","Arco"]}},"cena":{"order":2,"default":"Renas","ui":{"label":"Cena","widget":"select","options":["Renas","Pinheiros","Presépio","Trenó","Casinhas"]}},"largura":{"order":3,"type":"number","min":70,"max":220,"unit":"mm","default":120,"ui":{"label":"Largura da moldura","widget":"slider","step":1}},"espessura":{"order":4,"type":"number","min":2.4,"max":8,"unit":"mm","default":4,"ui":{"label":"Espessura da moldura","widget":"slider","step":0.2}},"diametro_vela":{"order":5,"type":"number","min":30,"max":60,"unit":"mm","default":39.5,"ui":{"label":"Diâmetro da cavidade da vela","widget":"slider","step":0.5}},"pecas":{"order":6,"default":"Moldura e base","ui":{"label":"Peças","widget":"select","options":["Moldura e base","Só a moldura","Só a base"]}},"info_cena":{"order":99,"default":null,"ui":{"widget":"info","text":"✨ A moldura e a base imprimem-se deitadas, lado a lado, sem suportes; depois a moldura encaixa de pé na ranhura da base (a pré-visualização mostra-a montada). A vela LED fica atrás da cena. Recomendamos velas LED (as cavidades são para velas de chá LED, 38 × 16 mm, com folga). Nunca uses velas a sério: o plástico amolece e arde."}}}}'::jsonb, '{}'::jsonb)
on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, tags = excluded.tags,
  scad_template = excluded.scad_template, generation_schema = excluded.generation_schema;
